// Superseded by estimateRange (T14) — kept for provenance and any legacy reads.
export function lookupBand(miles) {
  return DISPATCH_RATE_BANDS.find(
    (b) => miles >= b.minMiles && (b.maxMiles === null || miles <= b.maxMiles)
  ) || null;
}

export const RATE_CURVE = [{"m":25,"dpm":3.8406,"n":26},{"m":101,"dpm":2.1229,"n":63},{"m":226,"dpm":1.0753,"n":80},{"m":401,"dpm":0.7826,"n":92},{"m":651,"dpm":0.7158,"n":54},{"m":1001,"dpm":0.5624,"n":47},{"m":1273,"dpm":0.5715,"n":10}]; // recentered: raw x globalMed 0.9234
export const TAIL_FLOOR_DPM = 0.45;
export const ORIGIN_ADJ = {"FL":0.926,"TX":0.927,"CA":1.014,"IL":1.036,"AZ":0.959,"OH":1.15,"VA":1.142,"GA":1.006,"IN":1.128,"MA":1.15,"PA":0.952,"CO":0.924,"NC":0.927};

export function curveMid(miles) {
  const pts = RATE_CURVE;
  let dpm;
  if (miles <= pts[0].m) dpm = pts[0].dpm;
  else {
    dpm = null;
    for (let i = 0; i < pts.length - 1; i++) {
      if (miles <= pts[i + 1].m) {
        const a = pts[i], b = pts[i + 1];
        dpm = a.dpm + (b.dpm - a.dpm) * ((miles - a.m) / (b.m - a.m));
        break;
      }
    }
    if (dpm === null) {
      const a = pts[pts.length - 2], b = pts[pts.length - 1];
      const slope = Math.min(0, (b.dpm - a.dpm) / (b.m - a.m)); // flat-tail rule
      dpm = Math.max(TAIL_FLOOR_DPM, b.dpm + slope * (miles - b.m));
    }
  }
  return dpm * miles;
}

const _round5 = (n) => Math.round(n / 5) * 5;

// T14 runtime entry point: typical carrier range for a route.
// mult folds the vehicle/transport multipliers in (1 = none).
export function estimateRange(miles, originState, mult = 1) {
  if (!(miles > 0)) return null;
  let band = lookupBand(miles);
  // Tail spread rule: the 1200+ band is too thin (n=11) to estimate spread —
  // its raw P25/P75 ratios read +/-25%. Long-haul ranges borrow the adjacent
  // 801-1200 ratios (largest nearby sample, ~+/-10%: the sprint's target
  // width), applied to the continuous mid.
  if (band && band.maxMiles === null) {
    band = DISPATCH_RATE_BANDS[DISPATCH_RATE_BANDS.length - 2];
  }
  const adj = (originState && ORIGIN_ADJ[originState]) || 1;
  const mid = curveMid(miles) * adj * mult;
  return {
    miles,
    mid: Math.round(mid),
    lo: _round5(mid * band.loRatio),
    hi: _round5(mid * band.hiRatio),
  };
}

